import{_ as s,a as o,c as n,ac as l}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第一册：英语初阶 · 全册短语与句型 · 第84–111课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第一册：英语初阶 · 全册短语与句型 · 第84–111课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-1/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册短语与句型 · 第56–83课","link":"/life/english/new-concept/book-1/phrases-part-03"},"next":{"text":"第一册：英语初阶 · 全册短语与句型 · 第112–137课","link":"/life/english/new-concept/book-1/phrases-part-05"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册短语与句型 · 第56–83课","link":"/life/english/new-concept/book-1/phrases-part-03"},"next":{"text":"第一册：英语初阶 · 全册短语与句型 · 第112–137课","link":"/life/english/new-concept/book-1/phrases-part-05"}},"headers":[],"relativePath":"life/english/new-concept/book-1/phrases-part-04.md","filePath":"life/english/new-concept/book-1/phrases-part-04.md"}'),a={name:"life/english/new-concept/book-1/phrases-part-04.md"};function t(i,e,r,h,p,c){return o(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="第一册-英语初阶-·-全册短语与句型-·-第84–111课" tabindex="-1">第一册：英语初阶 · 全册短语与句型 · 第84–111课 <a class="header-anchor" href="#第一册-英语初阶-·-全册短语与句型-·-第84–111课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册短语与句型 · 第84–111课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="lesson-84-·-现在完成时入门" tabindex="-1">Lesson 84 · 现在完成时入门 <a class="header-anchor" href="#lesson-84-·-现在完成时入门" aria-label="Permalink to &quot;Lesson 84 · 现在完成时入门 {#lesson-84-·-现在完成时入门}&quot;">​</a></h2><ul><li>have already packed — 已收拾好</li><li>go on holiday — 去度假</li></ul><p><strong>句型示范：</strong> Have you checked the train times yet?</p><p>Have 前置，checked 为过去分词；yet 位于句末，询问截至现在是否已完成核查。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-084">进入本课</a></p><h2 id="lesson-85-·-have-been-to-与过去时间" tabindex="-1">Lesson 85 · have been to 与过去时间 <a class="header-anchor" href="#lesson-85-·-have-been-to-与过去时间" aria-label="Permalink to &quot;Lesson 85 · have been to 与过去时间 {#lesson-85-·-have-been-to-与过去时间}&quot;">​</a></h2><ul><li>have been to — 去过而已返回</li><li>have gone to — 已去尚未返回</li></ul><p><strong>句型示范：</strong> I have been to Vienna twice.</p><p>Have been to 表过去去过且已经返回；twice 说明经历次数，不给出具体已结束的日期。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-085">进入本课</a></p><h2 id="lesson-86-·-have-been-to-与过去时间" tabindex="-1">Lesson 86 · have been to 与过去时间 <a class="header-anchor" href="#lesson-86-·-have-been-to-与过去时间" aria-label="Permalink to &quot;Lesson 86 · have been to 与过去时间 {#lesson-86-·-have-been-to-与过去时间}&quot;">​</a></h2><ul><li>have been to — 去过而已返回</li><li>have gone to — 已去尚未返回</li></ul><p><strong>句型示范：</strong> Rita has gone to the bank and will be back soon.</p><p>Has gone to 表丽塔已经离开去银行；will be back soon 提示她尚未回来，soon 是未来时间提示。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-086">进入本课</a></p><h2 id="lesson-87-·-现在完成时的疑问与否定" tabindex="-1">Lesson 87 · 现在完成时的疑问与否定 <a class="header-anchor" href="#lesson-87-·-现在完成时的疑问与否定" aria-label="Permalink to &quot;Lesson 87 · 现在完成时的疑问与否定 {#lesson-87-·-现在完成时的疑问与否定}&quot;">​</a></h2><ul><li>has not repaired — 尚未修好</li><li>have you checked yet — 询问是否已检查</li></ul><p><strong>句型示范：</strong> The mechanic has not repaired my bicycle yet.</p><p>Has not repaired 为现在完成时否定；yet 放句末，表示截至目前仍未完成。my bicycle 为修理对象。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-087">进入本课</a></p><h2 id="lesson-88-·-现在完成时的疑问与否定" tabindex="-1">Lesson 88 · 现在完成时的疑问与否定 <a class="header-anchor" href="#lesson-88-·-现在完成时的疑问与否定" aria-label="Permalink to &quot;Lesson 88 · 现在完成时的疑问与否定 {#lesson-88-·-现在完成时的疑问与否定}&quot;">​</a></h2><ul><li>has not repaired — 尚未修好</li><li>have you checked yet — 询问是否已检查</li></ul><p><strong>句型示范：</strong> Have they replaced the broken window yet?</p><p>Have they replaced 询问完成结果；broken 是修饰 window 的过去分词形容词，yet 询问是否已经。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-088">进入本课</a></p><h2 id="lesson-89-·-since-与-for" tabindex="-1">Lesson 89 · since 与 for <a class="header-anchor" href="#lesson-89-·-since-与-for" aria-label="Permalink to &quot;Lesson 89 · since 与 for {#lesson-89-·-since-与-for}&quot;">​</a></h2><ul><li>for sale — 待售</li><li>how long — 询问持续多久</li></ul><p><strong>句型示范：</strong> We have lived here for six years.</p><p>Have lived 表从过去持续到现在的居住；for six years 给出持续时长，不是起始日期。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-089">进入本课</a></p><h2 id="lesson-90-·-since-与-for" tabindex="-1">Lesson 90 · since 与 for <a class="header-anchor" href="#lesson-90-·-since-与-for" aria-label="Permalink to &quot;Lesson 90 · since 与 for {#lesson-90-·-since-与-for}&quot;">​</a></h2><ul><li>for sale — 待售</li><li>how long — 询问持续多久</li></ul><p><strong>句型示范：</strong> She has owned this flat since 2020.</p><p>Has owned 表持续的拥有状态；since 2020 给出起点，与延续到现在的状态配合。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-090">进入本课</a></p><h2 id="lesson-91-·-will-表将来" tabindex="-1">Lesson 91 · will 表将来 <a class="header-anchor" href="#lesson-91-·-will-表将来" aria-label="Permalink to &quot;Lesson 91 · will 表将来 {#lesson-91-·-will-表将来}&quot;">​</a></h2><ul><li>will move — 将搬家</li><li>will be ready — 将准备好</li></ul><p><strong>句型示范：</strong> Our neighbours will move next month.</p><p>Our neighbours 为复数主语，但 will 对所有人称同形；move 用原形，next month 是将来时间。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-091">进入本课</a></p><h2 id="lesson-92-·-will-表将来" tabindex="-1">Lesson 92 · will 表将来 <a class="header-anchor" href="#lesson-92-·-will-表将来" aria-label="Permalink to &quot;Lesson 92 · will 表将来 {#lesson-92-·-will-表将来}&quot;">​</a></h2><ul><li>will move — 将搬家</li><li>will be ready — 将准备好</li></ul><p><strong>句型示范：</strong> Will the new room be ready tomorrow?</p><p>Will 提前构成问句，the new room 为主语，be ready 构成系表结构；be 不能遗漏。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-092">进入本课</a></p><h2 id="lesson-93-·-过去、现在与将来的时间线" tabindex="-1">Lesson 93 · 过去、现在与将来的时间线 <a class="header-anchor" href="#lesson-93-·-过去、现在与将来的时间线" aria-label="Permalink to &quot;Lesson 93 · 过去、现在与将来的时间线 {#lesson-93-·-过去、现在与将来的时间线}&quot;">​</a></h2><ul><li>last year — 已结束的过去</li><li>next week — 将来的时间</li></ul><p><strong>句型示范：</strong> Our neighbour flew to Madrid last week.</p><p>Flew 是 fly 的过去式，last week 指明确过去；to Madrid 表飞行目的地。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-093">进入本课</a></p><h2 id="lesson-94-·-过去、现在与将来的时间线" tabindex="-1">Lesson 94 · 过去、现在与将来的时间线 <a class="header-anchor" href="#lesson-94-·-过去、现在与将来的时间线" aria-label="Permalink to &quot;Lesson 94 · 过去、现在与将来的时间线 {#lesson-94-·-过去、现在与将来的时间线}&quot;">​</a></h2><ul><li>last year — 已结束的过去</li><li>next week — 将来的时间</li></ul><p><strong>句型示范：</strong> He will return next Tuesday.</p><p>Will return 为将来结构，return 用原形；next Tuesday 前不用 on。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-094">进入本课</a></p><h2 id="lesson-95-·-had-better-与时间表达" tabindex="-1">Lesson 95 · had better 与时间表达 <a class="header-anchor" href="#lesson-95-·-had-better-与时间表达" aria-label="Permalink to &quot;Lesson 95 · had better 与时间表达 {#lesson-95-·-had-better-与时间表达}&quot;">​</a></h2><ul><li>had better leave — 最好现在出发</li><li>had better not wait — 最好不要等</li></ul><p><strong>句型示范：</strong> We had better leave before the traffic gets heavy.</p><p>Had better 后直接接 leave，表示当前建议；before the traffic gets heavy 是时间从句，用现在时表达将来。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-095">进入本课</a></p><h2 id="lesson-96-·-had-better-与时间表达" tabindex="-1">Lesson 96 · had better 与时间表达 <a class="header-anchor" href="#lesson-96-·-had-better-与时间表达" aria-label="Permalink to &quot;Lesson 96 · had better 与时间表达 {#lesson-96-·-had-better-与时间表达}&quot;">​</a></h2><ul><li>had better leave — 最好现在出发</li><li>had better not wait — 最好不要等</li></ul><p><strong>句型示范：</strong> You had better not miss the last train.</p><p>Had better not 加 miss 表否定建议；the last train 为宾语，had better 不是过去发生的动作。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-096">进入本课</a></p><h2 id="lesson-97-·-名词性物主代词" tabindex="-1">Lesson 97 · 名词性物主代词 <a class="header-anchor" href="#lesson-97-·-名词性物主代词" aria-label="Permalink to &quot;Lesson 97 · 名词性物主代词 {#lesson-97-·-名词性物主代词}&quot;">​</a></h2><ul><li>a small blue case — 尺寸在颜色前</li><li>this one is mine — mine 独立作表语</li></ul><p><strong>句型示范：</strong> The small green suitcase is mine.</p><p>The small green suitcase 是主语，small 表尺寸、green 表颜色；mine 独立作表语，后不再接 suitcase。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-097">进入本课</a></p><h2 id="lesson-98-·-名词性物主代词" tabindex="-1">Lesson 98 · 名词性物主代词 <a class="header-anchor" href="#lesson-98-·-名词性物主代词" aria-label="Permalink to &quot;Lesson 98 · 名词性物主代词 {#lesson-98-·-名词性物主代词}&quot;">​</a></h2><ul><li>a small blue case — 尺寸在颜色前</li><li>this one is mine — mine 独立作表语</li></ul><p><strong>句型示范：</strong> Are these keys yours or hers?</p><p>These keys 为复数主语，are 前置；yours 与 hers 都独立代表“某人的钥匙”，两者之间用 or 提供选择。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-098">进入本课</a></p><h2 id="lesson-99-·-现在时引述与宾语从句" tabindex="-1">Lesson 99 · 现在时引述与宾语从句 <a class="header-anchor" href="#lesson-99-·-现在时引述与宾语从句" aria-label="Permalink to &quot;Lesson 99 · 现在时引述与宾语从句 {#lesson-99-·-现在时引述与宾语从句}&quot;">​</a></h2><ul><li>says that — 引出转述内容</li><li>tells me that — tell 后接听话的人</li></ul><p><strong>句型示范：</strong> Ben says that his ankle hurts.</p><p>Ben says 是主句，that his ankle hurts 是宾语从句；ankle 单数，所以从句谓语 hurt 加 s。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-099">进入本课</a></p><h2 id="lesson-100-·-现在时引述与宾语从句" tabindex="-1">Lesson 100 · 现在时引述与宾语从句 <a class="header-anchor" href="#lesson-100-·-现在时引述与宾语从句" aria-label="Permalink to &quot;Lesson 100 · 现在时引述与宾语从句 {#lesson-100-·-现在时引述与宾语从句}&quot;">​</a></h2><ul><li>says that — 引出转述内容</li><li>tells me that — tell 后接听话的人</li></ul><p><strong>句型示范：</strong> She tells me that the floor is wet.</p><p>Tells 后接 me 表听话人，再接 that 从句；the floor is wet 使用完整陈述语序。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-100">进入本课</a></p><h2 id="lesson-101-·-间接引语中的人称转换" tabindex="-1">Lesson 101 · 间接引语中的人称转换 <a class="header-anchor" href="#lesson-101-·-间接引语中的人称转换" aria-label="Permalink to &quot;Lesson 101 · 间接引语中的人称转换 {#lesson-101-·-间接引语中的人称转换}&quot;">​</a></h2><ul><li>send a card — 寄明信片</li><li>says she is — 人称转换后的引述</li></ul><p><strong>句型示范：</strong> Rita says she is staying with her aunt.</p><p>Rita says 是现在时引述；she 与 her 都指 Rita，is staying 描述她现阶段的居住安排。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-101">进入本课</a></p><h2 id="lesson-102-·-间接引语中的人称转换" tabindex="-1">Lesson 102 · 间接引语中的人称转换 <a class="header-anchor" href="#lesson-102-·-间接引语中的人称转换" aria-label="Permalink to &quot;Lesson 102 · 间接引语中的人称转换 {#lesson-102-·-间接引语中的人称转换}&quot;">​</a></h2><ul><li>send a card — 寄明信片</li><li>says she is — 人称转换后的引述</li></ul><p><strong>句型示范：</strong> The boys say they will arrive tomorrow.</p><p>The boys say 是复数主语和原形谓语；从句 they will arrive 表将来，tomorrow 按当前转述时间理解。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-102">进入本课</a></p><h2 id="lesson-103-·-too-very-enough" tabindex="-1">Lesson 103 · too/very/enough <a class="header-anchor" href="#lesson-103-·-too-very-enough" aria-label="Permalink to &quot;Lesson 103 · too/very/enough {#lesson-103-·-too-very-enough}&quot;">​</a></h2><ul><li>enough time — enough 位于名词前</li><li>easy enough — enough 位于形容词后</li></ul><p><strong>句型示范：</strong> The instructions are clear enough to follow.</p><p>Clear 是表语，enough 放在形容词之后；to follow 说明足够清楚所能完成的活动。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-103">进入本课</a></p><h2 id="lesson-104-·-too-very-enough" tabindex="-1">Lesson 104 · too/very/enough <a class="header-anchor" href="#lesson-104-·-too-very-enough" aria-label="Permalink to &quot;Lesson 104 · too/very/enough {#lesson-104-·-too-very-enough}&quot;">​</a></h2><ul><li>enough time — enough 位于名词前</li><li>easy enough — enough 位于形容词后</li></ul><p><strong>句型示范：</strong> This suitcase is too heavy for me to lift.</p><p>Too heavy 表超过能力范围；for me 指动作执行者，to lift 给出因太重而无法完成的动作。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-104">进入本课</a></p><h2 id="lesson-105-·-动词-宾语-to-do" tabindex="-1">Lesson 105 · 动词 + 宾语 + to do <a class="header-anchor" href="#lesson-105-·-动词-宾语-to-do" aria-label="Permalink to &quot;Lesson 105 · 动词 + 宾语 + to do {#lesson-105-·-动词-宾语-to-do}&quot;">​</a></h2><ul><li>ask someone to — 请某人做</li><li>full of mistakes — 充满错误</li></ul><p><strong>句型示范：</strong> Please ask Leo to check the figures.</p><p>Ask 为祈使句谓语，Leo 为宾语，to check 为宾语补足语；实际执行 check 的人是 Leo。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-105">进入本课</a></p><h2 id="lesson-106-·-动词-宾语-to-do" tabindex="-1">Lesson 106 · 动词 + 宾语 + to do <a class="header-anchor" href="#lesson-106-·-动词-宾语-to-do" aria-label="Permalink to &quot;Lesson 106 · 动词 + 宾语 + to do {#lesson-106-·-动词-宾语-to-do}&quot;">​</a></h2><ul><li>ask someone to — 请某人做</li><li>full of mistakes — 充满错误</li></ul><p><strong>句型示范：</strong> I told her not to send the draft yet.</p><p>Told 为过去式，her 为宾语；not to send 是否定不定式，yet 表暂时仍不要发送。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-106">进入本课</a></p><h2 id="lesson-107-·-形容词比较级" tabindex="-1">Lesson 107 · 形容词比较级 <a class="header-anchor" href="#lesson-107-·-形容词比较级" aria-label="Permalink to &quot;Lesson 107 · 形容词比较级 {#lesson-107-·-形容词比较级}&quot;">​</a></h2><ul><li>larger than — 比……大</li><li>more expensive — 更贵</li></ul><p><strong>句型示范：</strong> This backpack is lighter than that one.</p><p>Lighter 是 light 的比较级；than that one 引出同类比较对象，one 替代 backpack。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-107">进入本课</a></p><h2 id="lesson-108-·-形容词比较级" tabindex="-1">Lesson 108 · 形容词比较级 <a class="header-anchor" href="#lesson-108-·-形容词比较级" aria-label="Permalink to &quot;Lesson 108 · 形容词比较级 {#lesson-108-·-形容词比较级}&quot;">​</a></h2><ul><li>larger than — 比……大</li><li>more expensive — 更贵</li></ul><p><strong>句型示范：</strong> The blue jacket is more expensive than the grey one.</p><p>More expensive 是多音节形容词比较级；the grey one 替代 the grey jacket，避免重复名词。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-108">进入本课</a></p><h2 id="lesson-109-·-much-many-的比较级" tabindex="-1">Lesson 109 · much/many 的比较级 <a class="header-anchor" href="#lesson-109-·-much-many-的比较级" aria-label="Permalink to &quot;Lesson 109 · much/many 的比较级 {#lesson-109-·-much-many-的比较级}&quot;">​</a></h2><ul><li>less sugar — 更少的糖</li><li>fewer cups — 更少的杯子</li></ul><p><strong>句型示范：</strong> This recipe needs less sugar than the old one.</p><p>Needs 与单数主语 this recipe 一致；less 修饰不可数 sugar，than the old one 比较两个配方。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-109">进入本课</a></p><h2 id="lesson-110-·-much-many-的比较级" tabindex="-1">Lesson 110 · much/many 的比较级 <a class="header-anchor" href="#lesson-110-·-much-many-的比较级" aria-label="Permalink to &quot;Lesson 110 · much/many 的比较级 {#lesson-110-·-much-many-的比较级}&quot;">​</a></h2><ul><li>less sugar — 更少的糖</li><li>fewer cups — 更少的杯子</li></ul><p><strong>句型示范：</strong> We used fewer paper cups this week.</p><p>Used 为过去式，fewer 修饰复数可数名词 paper cups；this week 在这里指本周已发生的用杯情况。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-110">进入本课</a></p><h2 id="lesson-111-·-形容词最高级" tabindex="-1">Lesson 111 · 形容词最高级 <a class="header-anchor" href="#lesson-111-·-形容词最高级" aria-label="Permalink to &quot;Lesson 111 · 形容词最高级 {#lesson-111-·-形容词最高级}&quot;">​</a></h2><ul><li>the most expensive — 最贵的</li><li>the best choice — 最佳选择</li></ul><p><strong>句型示范：</strong> This is the lightest laptop in the shop.</p><p>The lightest 为最高级，in the shop 限定比较范围；laptop 是被选中的类别名词。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-111">进入本课</a></p>',143)])])}const g=s(a,[["render",t]]);export{d as __pageData,g as default};
